import {savingDistributionSource as source} from './planning-saving-distribution-data.js';
export const savingDistributionDefinitions={
  savingDistribution:{title:'Explore a historical income-group mean and its reference year',fields:[
    ['netSavingYear','Year to display (2021–2025 release snapshot)',2025,2021,2025,1],
    ['netSavingCompare','Reference year for the difference chart',2021,2021,2025,1],
    ['netSavingGroup','Income group to trace: 1 lowest, 3 middle, 5 highest',3,1,5,1]
  ]}
};
export function savingDistributionComparison(input){
  const current=source.years.indexOf(input.netSavingYear),reference=source.years.indexOf(input.netSavingCompare),group=source.groups[input.netSavingGroup-1];
  return {group,selected:group.values[current],change:group.values[current]-group.values[reference],gap:source.groups.at(-1).values[current]-source.groups[0].values[current],current,reference};
}
export function savingDistributionResult(kind,input){
  if(kind!=='savingDistribution')throw Error('Unknown saving-distribution topic.');
  const p=savingDistributionComparison(input),common={source:source.url,sourceLabel:'Statistics Canada · annual net-saving means · 13 April 2026 snapshot'};
  return {metrics:[['Selected '+p.group.short.toLowerCase()+' group · '+input.netSavingYear+' average net saving per household',p.selected,'money'],['Selected group: '+input.netSavingYear+' minus '+input.netSavingCompare,p.change,'money'],['Highest-minus-lowest group means in '+input.netSavingYear,p.gap,'money']],note:'All charts use the same public 13 April 2026 release vintage, with 25 annual observations for 2021–2025. Units are current CAD per household per year, not thousands or millions, a percentage, a median, an account balance or a saving target. Controls select historical observations and subtract them; they do not forecast, locate the reader in an income quintile or create a personal cash budget. Group membership need not be the same across years. A negative group mean does not reveal how many individual households have negative net saving. No confidence interval, significance test, causal attribution or within-group distribution is supplied.',charts:[
    {id:'saving-distribution-levels',type:'signedbar',title:'Average annual net saving differs across the five income groups in '+input.netSavingYear,unit:'money',unitLabel:'Current CAD per household per year · income-quintile means',rows:source.groups.map(group=>({label:group.label,value:group.values[p.current]})),...common,note:'Signed group averages in the selected historical year. Negative values are net dissaving on the source’s national-accounts definition; positive values are net saving. They are not each household’s result, end-of-year wealth or the number of people who saved. No income thresholds are inferred from the chart.'},
    {id:'saving-distribution-changes',type:'signedbar',title:'Subtract '+input.netSavingCompare+' from '+input.netSavingYear+' before describing the change',unit:'money',unitLabel:'Change in average annual net saving · current CAD per household',rows:source.groups.map(group=>({label:group.label,value:group.values[p.current]-group.values[p.reference]})),...common,evidence:'Derived from official statistics',note:'Each difference is selected-year mean minus reference-year mean, using one release vintage. A positive difference can mean a smaller negative mean rather than positive saving. If the selected year is earlier than the reference, the subtraction deliberately reverses direction. Identical years give zero. Differences are nominal and are not adjusted for inflation or changing group membership.'},
    {id:'saving-distribution-group-history',type:'line',title:p.group.label+': five annual means around an explicit zero line',unit:'money',unitLabel:'Average annual net saving · current CAD per household',xLabel:'Calendar year',xTicks:[0,2,4].map(index=>({value:index,label:String(source.years[index])})),yMax:p.group.values.every(v=>v<=0)?0:undefined,series:[{name:p.group.label,rows:source.years.map((year,i)=>({x:i,label:String(year),value:p.group.values[i]}))},{name:'Zero net saving comparison',dash:true,rows:[{x:0,value:0},{x:4,value:0}]}],...common,note:'The five observations correspond to 2021 through 2025, with exact calendar years in the data table. The connected line summarizes annual group means; it is not a monthly path or a panel following the same households. The zero line distinguishes a negative level from an improving change. Both year selectors leave this complete five-year history unchanged; the income-group selector changes it.'},
    {id:'saving-distribution-snapshot-matrix',type:'heatmap',title:'Three annual snapshots retain the sign as well as the size',unit:'money',signed:true,unitLabel:'Current CAD per household per year · annual group means',columns:['2021','2023','2025'],rows:source.groups.map(group=>({label:group.short,values:[0,2,4].map(index=>group.values[index])})),...common,note:'This fixed comparison displays all five groups in three selected annual snapshots from the same source. Gold denotes negative values and teal positive values; exact signed amounts remain in the data table. It does not rank household effort, show income cutoffs or measure the fraction of individual households in deficit. Neither historical-year selector changes this context matrix.'}
  ]};
}
